<?php require_once __DIR__.'/includes/config.php'; $pdo=db(true); ?><!doctype html><html lang="es"><head><meta charset="utf-8"><title>ESG — Diagnóstico</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1>Diagnóstico ESG</h1><?php if(!$pdo): ?><div class="alert alert-danger">No se pudo conectar a la base de datos. Revise includes/config.php o las variables ESG_DB_*.</div><?php else: ?><div class="alert alert-success">Conexión correcta.</div><h3>Tablas</h3><ul><?php foreach($pdo->query('SHOW TABLES') as $r) echo '<li>'.e(array_values($r)[0]).'</li>'; ?></ul><h3>Usuarios</h3><div class="table-responsive"><table class="table table-bordered bg-white"><tr><th>PC</th><th>Usuario</th><th>Rol</th><th>Activo</th><th>Estado PC</th></tr><?php foreach($pdo->query('SELECT pc_identificador,nombre_usuario,rol,activo,estado_pc FROM usuarios ORDER BY id') as $r) echo '<tr><td>'.e($r['pc_identificador']).'</td><td>'.e($r['nombre_usuario']).'</td><td>'.e($r['rol']).'</td><td>'.($r['activo']?'Sí':'No').'</td><td>'.e($r['estado_pc']).'</td></tr>'; ?></table></div><?php endif; ?></main></body></html>
